private void decodeForm(HttpRequest req, Formdata form) {
    if ((decoder == null) || (decoder instanceof HttpRawPostRequestDecoder)) {
        // empty/bad form
        return;
    }
    try {
        while (decoder.hasNext()) {
            HttpData next = ((HttpData) (decoder.next()));
            if (next.getHttpDataType() == InterfaceHttpData.HttpDataType.FileUpload) {
                ((Multipart) (form)).put(next.getName(), register(new NettyFileUpload(router.getTmpdir(), ((FileUpload) (next)))));
            } else {
                form.put(next.getName(), next.getString(UTF_8));
            }
        } 
    } catch (HttpPostRequestDecoder.EndOfDataDecoderException x) {
        // ignore, silly netty
    } catch (Exception x) {
        throw SneakyThrows.propagate(x);
    } finally {
        release(req);
    }
}

void destroy(Throwable cause) {
    if (cause != null) {
        if (Server.connectionLost(cause)) {
            router.getLog().debug("exception found while sending response {} {}", getMethod(), getRequestPath(), cause);
        } else {
            router.getLog().error("exception found while sending response {} {}", getMethod(), getRequestPath(), cause);
        }
    }
    if (files != null) {
        for (FileUpload file : files) {
            try {
                file.destroy();
            } catch (Exception x) {
                router.getLog().debug("file upload destroy resulted in exception", x);
            }
        }
        files = null;
    }
    if (decoder != null) {
        try {
            decoder.destroy();
        } catch (Exception x) {
            router.getLog().debug("body decoder destroy resulted in exception", x);
        }
        decoder = null;
    }
    release(req);
}

