@Override
public Context send(@Nonnull
FileChannel file) {
    try {
        long len = file.size();
        setHeaders.set(CONTENT_LENGTH, Long.toString(len));
        ByteRange range = ByteRange.parse(req.headers().get(RANGE), len).apply(this);
        DefaultHttpResponse rsp = new DefaultHttpResponse(HTTP_1_1, status, setHeaders);
        responseStarted = true;
        if (isSecure() || isGzip()) {
            prepareChunked();
            HttpChunkedInput chunkedInput = new HttpChunkedInput(new ChunkedNioFile(file, range.getStart(), range.getEnd(), bufferSize));
            ctx.channel().eventLoop().execute(() -> {
                // Headers
                ctx.write(rsp, ctx.voidPromise());
                // Body
                ctx.writeAndFlush(chunkedInput, promise(this));
            });
        } else {
            ctx.channel().eventLoop().execute(() -> {
                // Headers
                ctx.write(rsp, ctx.voidPromise());
                // Body
                ctx.write(new DefaultFileRegion(file, range.getStart(), range.getEnd()), ctx.voidPromise());
                // Finish
                ctx.writeAndFlush(EMPTY_LAST_CONTENT, promise(this));
            });
        }
    } catch (IOException x) {
        throw SneakyThrows.propagate(x);
    } finally {
        requestComplete();
    }
    return this;
}

