@Override
public Context upgrade(WebSocket.Initializer handler) {
    try {
        responseStarted = true;
        Config conf = getRouter().getConfig();
        int maxSize = (conf.hasPath("websocket.maxSize")) ? conf.getBytes("websocket.maxSize").intValue() : WebSocket.MAX_BUFFER_SIZE;
        String webSocketURL = ((getProtocol() + "://") + req.headers().get(HttpHeaderNames.HOST)) + path;
        WebSocketDecoderConfig config = WebSocketDecoderConfig.newBuilder().allowExtensions(true).allowMaskMismatch(false).withUTF8Validator(false).maxFramePayloadLength(maxSize).build();
        webSocket = new NettyWebSocket(this);
        handler.init(Context.readOnly(this), webSocket);
        FullHttpRequest webSocketRequest = new DefaultFullHttpRequest(req.protocolVersion(), req.method(), req.uri(), Unpooled.EMPTY_BUFFER, req.headers(), EmptyHttpHeaders.INSTANCE);
        WebSocketServerHandshakerFactory factory = new WebSocketServerHandshakerFactory(webSocketURL, null, config);
        WebSocketServerHandshaker handshaker = factory.newHandshaker(webSocketRequest);
        handshaker.handshake(ctx.channel(), webSocketRequest);
        webSocket.fireConnect();
        long timeout = (conf.hasPath("websocket.idleTimeout")) ? conf.getDuration("websocket.idleTimeout", MILLISECONDS) : MINUTES.toMillis(5);
        if (timeout > 0) {
            IdleStateHandler idle = new IdleStateHandler(timeout, 0, 0, MILLISECONDS);
            ctx.pipeline().addBefore("handler", "idle", idle);
        }
    } catch (Throwable x) {
        sendError(x);
    }
    return this;
}

