public WebSocket render(Object value, boolean broadcast) {
    if (broadcast) {
        for (WebSocket ws : all.getOrDefault(key, Collections.emptyList())) {
            ws.render(value, false);
        }
    } else {
        try {
            Context.websocket(netty, this).render(value);
        } catch (Throwable x) // PATH: Test should invoke the next NettyWebSocket.handleError(...) [step in execution path]
        {
            handleError(x);
        }
    }
    return this;
}

private void handleError(Throwable x) {
    // should close?
    if (Server.connectionLost(x) || SneakyThrows.isFatal(x)) {
        handleClose(WebSocketCloseStatus.SERVER_ERROR);
    }
    if (onErrorCallback == null) {
        netty.getRouter().getLog().error("Websocket resulted in exception: {}", netty.getRequestPath(), x);
    } else {
        onErrorCallback.onError(this, x);
    }
    if (SneakyThrows.isFatal(x)) {
        this.netty.ctx.channel().attr(WS).set(null);
        throw SneakyThrows.propagate(x);
    }
}

