@Override
public Server start(@Nonnull
Jooby application) {
    try {
        applications.add(application);
        addShutdownHook();
        /**
         * Worker: Application blocking code
         */
        worker = Executors.newFixedThreadPool(options.getWorkerThreads(), new DefaultThreadFactory("worker"));
        fireStart(applications, worker);
        /**
         * Disk attributes:
         */
        String tmpdir = applications.get(0).getTmpdir().toString();
        DiskFileUpload.baseDirectory = tmpdir;
        DiskAttribute.baseDirectory = tmpdir;
        NettyTransport transport = NettyTransport.transport(application.getClassLoader());
        /**
         * Acceptor event-loop
         */
        this.acceptorloop = transport.createEventLoop(1, "acceptor", _50);
        /**
         * Event loop: processing connections, parsing messages and doing engine's internal work
         */
        this.eventloop = transport.createEventLoop(options.getIoThreads(), "eventloop", _100);
        /**
         * File data factory:
         */
        HttpDataFactory factory = new DefaultHttpDataFactory(options.getBufferSize());
        Http2Configurer<Http2Extension, ChannelInboundHandler> http2;
        if ((options.isHttp2() == null) || (options.isHttp2() == Boolean.TRUE)) {
            http2 = stream(spliteratorUnknownSize(ServiceLoader.load(Http2Configurer.class).iterator(), Spliterator.ORDERED), false).filter(it -> it.support(Http2Extension.class)).findFirst().orElse(null);
        } else {
            http2 = null;
        }
        /**
         * Bootstrap:
         */
        if (!options.isHttpsOnly()) {
            ServerBootstrap http = transport.configure(acceptorloop, eventloop).childHandler(newPipeline(factory, null, http2)).childOption(ChannelOption.SO_REUSEADDR, true).childOption(ChannelOption.TCP_NODELAY, true);
            http.bind(options.getHost(), options.getPort()).get();
        }
        if (options.isSSLEnabled()) {
            SSLContext javaSslContext = options.getSSLContext(application.getEnvironment().getClassLoader());
            SslOptions sslOptions = options.getSsl();
            String[] protocol = sslOptions.getProtocol().stream().toArray(String[]::new);
            SslOptions.ClientAuth clientAuth = sslOptions.getClientAuth();
            ServerBootstrap https = transport.configure(acceptorloop, eventloop).childHandler(// PATH: Test should invoke the next Netty.wrap(...) [step in execution path]
            newPipeline(factory, wrap(javaSslContext, toClientAuth(clientAuth), protocol, http2 != null), http2)).childOption(ChannelOption.SO_REUSEADDR, true).childOption(ChannelOption.TCP_NODELAY, true);
            https.bind(options.getHost(), options.getSecurePort()).get();
        } else if (options.isHttpsOnly()) {
            throw new IllegalArgumentException("Server configured for httpsOnly, but ssl options not set");
        }
        fireReady(applications);
    } catch (InterruptedException x) {
        throw SneakyThrows.propagate(x);
    } catch (ExecutionException x) {
        Throwable cause = x.getCause();
        if (Server.isAddressInUse(cause)) {
            cause = new BindException("Address already in use: " + options.getPort());
        }
        throw SneakyThrows.propagate(cause);
    }
    return this;
}

private SslContext wrap(SSLContext sslContext, ClientAuth clientAuth, String[] protocol, boolean http2) {
    ApplicationProtocolConfig protocolConfig;
    if (http2) {
        protocolConfig = new ApplicationProtocolConfig(ApplicationProtocolConfig.Protocol.ALPN, ApplicationProtocolConfig.SelectorFailureBehavior.NO_ADVERTISE, ApplicationProtocolConfig.SelectedListenerFailureBehavior.ACCEPT, Arrays.asList(ApplicationProtocolNames.HTTP_2, ApplicationProtocolNames.HTTP_1_1));
    } else {
        protocolConfig = ApplicationProtocolConfig.DISABLED;
    }
    JdkSslContext jdk = new JdkSslContext(sslContext, false, null, IdentityCipherSuiteFilter.INSTANCE, protocolConfig, clientAuth, protocol, false);
    return jdk;
}

