    if (pipeline.get("chunker") == null) {
        String base = Stream.of("compressor", "codec", "http2").filter(name -> pipeline.get(name) != null).findFirst().orElseThrow(() -> new IllegalStateException("No available handler for chunk writer"));
        pipeline.addAfter(base, "chunker", new ChunkedWriteHandler());
    }
    if (!setHeaders.contains(CONTENT_LENGTH)) {
        setHeaders.set(TRANSFER_ENCODING, CHUNKED);
    }
}

